def verify_pkcs7_8(blk: list[int]):
    pad = blk[7]
    steps = 0
    if pad == 0 or pad > 8:
        return (False, steps, "bad_len")
    for k in range(pad):
        steps += 1
        if blk[7 - k] != pad:
            return (False, steps, "bad_byte")
    return (True, steps, "ok")

# B1 = [1, 2, 3, 4, 5, 3, 3, 3]
# B2 = [1, 2, 3, 4, 5, 3, 9, 3]
# B3 = [1, 2, 3, 4, 5, 6, 7, 0]
# B4 = [1, 2, 3, 4, 5, 6, 7, 1]
```

